import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { QrCode, Maximize2, X, Download, Check, Sparkles } from 'lucide-react';
import defaultQrImage from '../assets/qr.png';

/**
 * QRCode Component
 * 
 * High-definition, responsive QR code component optimized for GitHub Pages.
 * Automatically bundles assets via Webpack with fallback support.
 */
export const QRCode = React.memo(({
  src = defaultQrImage,
  alt = "UPI QR Code for Shagun",
  title = "Ansh's UPI QR",
  subtitle = "Scan with GPay, PhonePe, Paytm or any UPI App",
  size = "md", // 'sm' | 'md' | 'lg'
  allowZoom = true,
  className = "",
}) => {
  const [hasError, setHasError] = useState(false);
  const [isZoomed, setIsZoomed] = useState(false);
  const [downloaded, setDownloaded] = useState(false);

  // Size configurations
  const sizeMap = {
    sm: 'w-36 h-36 sm:w-40 sm:h-40',
    md: 'w-48 h-48 sm:w-56 sm:h-56',
    lg: 'w-60 h-60 sm:w-72 sm:h-72',
  };

  const currentSrc = hasError 
    ? (process.env.PUBLIC_URL ? `${process.env.PUBLIC_URL}/qr.png` : '/qr.png')
    : (src || defaultQrImage);

  const handleDownload = (e) => {
    e.stopPropagation();
    const link = document.createElement('a');
    link.href = currentSrc;
    link.download = 'ansh-rakhi-shagun-qr.png';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setDownloaded(true);
    setTimeout(() => setDownloaded(false), 2000);
  };

  return (
    <div className={`relative flex flex-col items-center ${className}`}>
      {/* Interactive QR Display Card */}
      <div className="relative group">
        {/* Glow backdrop behind QR */}
        <div className="absolute -inset-2 bg-gradient-to-r from-[#E8B84B]/30 via-[#FF7A45]/20 to-[#E8B84B]/30 rounded-3xl blur-md opacity-75 group-hover:opacity-100 transition duration-500" />

        {/* Outer Frame with Gold borders */}
        <div className="relative p-3 sm:p-3.5 bg-gradient-to-b from-stone-900 via-black to-stone-950 rounded-2xl border-2 border-[#E8B84B]/70 shadow-[0_10px_30px_rgba(0,0,0,0.8)] backdrop-blur-md">
          {/* Ornate Corner Accents */}
          <span className="absolute top-1.5 left-2 text-[#E8B84B] text-[10px] select-none pointer-events-none opacity-80">❖</span>
          <span className="absolute top-1.5 right-2 text-[#E8B84B] text-[10px] select-none pointer-events-none opacity-80">❖</span>
          <span className="absolute bottom-1.5 left-2 text-[#E8B84B] text-[10px] select-none pointer-events-none opacity-80">❖</span>
          <span className="absolute bottom-1.5 right-2 text-[#E8B84B] text-[10px] select-none pointer-events-none opacity-80">❖</span>

          {/* QR Code Container */}
          <motion.div
            whileHover={allowZoom ? { scale: 1.02 } : {}}
            className={`relative ${sizeMap[size] || sizeMap.md} bg-white p-3 rounded-xl flex items-center justify-center overflow-hidden shadow-inner cursor-pointer`}
            onClick={() => allowZoom && setIsZoomed(true)}
          >
            {!hasError ? (
              <img
                src={currentSrc}
                alt={alt}
                onError={() => setHasError(true)}
                className="w-full h-full object-contain rounded-lg transition-transform duration-300"
                loading="eager"
              />
            ) : (
              /* Stylized Fallback if image path is unavailable */
              <div className="w-full h-full flex flex-col items-center justify-center bg-stone-900 rounded-lg p-3 relative overflow-hidden">
                <div className="grid grid-cols-5 gap-2 w-full h-full opacity-60">
                  {Array.from({ length: 25 }).map((_, i) => (
                    <div
                      key={i}
                      className={`rounded-xs ${
                        i % 2 === 0 || i === 0 || i === 4 || i === 20 || i === 24 || i === 12
                          ? 'bg-[#E8B84B]'
                          : 'bg-stone-800'
                      }`}
                    />
                  ))}
                </div>
                <div className="absolute inset-0 m-auto w-12 h-12 rounded-full bg-[#7A1424] border-2 border-[#E8B84B] flex items-center justify-center shadow-xl">
                  <span className="text-[#E8B84B] text-sm font-bold font-serif">अंश</span>
                </div>
              </div>
            )}

            {/* Tap / Hover to Zoom Prompt */}
            {allowZoom && (
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-200 flex items-center justify-center rounded-xl backdrop-blur-[2px]">
                <div className="px-3 py-1.5 rounded-full bg-black/80 border border-[#E8B84B]/60 text-[#FDF3E7] text-xs font-medium flex items-center gap-1.5 shadow-lg">
                  <Maximize2 className="w-3.5 h-3.5 text-[#E8B84B]" />
                  <span>Click to Expand</span>
                </div>
              </div>
            )}
          </motion.div>
        </div>
      </div>

      {/* Subtitles & Badges */}
      {(title || subtitle) && (
        <div className="mt-4 text-center">
          {title && (
            <div className="text-xs font-cinzel font-semibold text-[#E8B84B] flex items-center justify-center gap-1.5">
              <Sparkles className="w-3 h-3 text-[#FF7A45]" />
              <span>{title}</span>
              <Sparkles className="w-3 h-3 text-[#FF7A45]" />
            </div>
          )}
          {subtitle && (
            <span className="text-xs text-[#FDF3E7]/80 mt-1 font-medium flex items-center justify-center gap-1.5 text-center">
              <QrCode className="w-3.5 h-3.5 text-[#FF7A45] shrink-0" />
              <span>{subtitle}</span>
            </span>
          )}
        </div>
      )}

      {/* Lightbox / Zoom Modal */}
      <AnimatePresence>
        {isZoomed && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setIsZoomed(false)}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/85 backdrop-blur-md"
          >
            <motion.div
              initial={{ scale: 0.85, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.85, opacity: 0 }}
              transition={{ type: "spring", damping: 25, stiffness: 300 }}
              onClick={(e) => e.stopPropagation()}
              className="relative max-w-sm w-full bg-gradient-to-b from-stone-900 to-black p-6 rounded-3xl border-2 border-[#E8B84B]/80 shadow-2xl flex flex-col items-center"
            >
              {/* Close Button */}
              <button
                onClick={() => setIsZoomed(false)}
                className="absolute top-4 right-4 p-2 rounded-full bg-white/10 hover:bg-white/20 text-[#FDF3E7] border border-white/20 transition-colors"
                aria-label="Close"
              >
                <X className="w-5 h-5" />
              </button>

              <h3 className="text-lg font-cinzel font-bold text-[#E8B84B] mb-1">
                Scan Shagun QR
              </h3>
              <p className="text-xs text-[#FDF3E7]/70 mb-5 text-center">
                Point any payment app camera to send your blessings
              </p>

              {/* Large QR Display */}
              <div className="w-64 h-64 sm:w-72 sm:h-72 bg-white p-4 rounded-2xl border-2 border-[#E8B84B] shadow-2xl flex items-center justify-center mb-5">
                <img
                  src={currentSrc}
                  alt={alt}
                  className="w-full h-full object-contain rounded-xl"
                />
              </div>

              {/* Actions Bar */}
              <div className="flex items-center gap-3 w-full">
                <button
                  onClick={handleDownload}
                  className="flex-1 py-2.5 px-4 rounded-xl bg-[#E8B84B]/20 hover:bg-[#E8B84B]/30 border border-[#E8B84B]/60 text-[#FDF3E7] text-xs font-semibold flex items-center justify-center gap-2 transition-all shadow-md"
                >
                  {downloaded ? (
                    <>
                      <Check className="w-4 h-4 text-emerald-400" />
                      <span className="text-emerald-300">Saved!</span>
                    </>
                  ) : (
                    <>
                      <Download className="w-4 h-4 text-[#E8B84B]" />
                      <span>Download QR</span>
                    </>
                  )}
                </button>
                <button
                  onClick={() => setIsZoomed(false)}
                  className="py-2.5 px-5 rounded-xl bg-white/10 hover:bg-white/15 border border-white/20 text-[#FDF3E7] text-xs font-semibold transition-all"
                >
                  Done
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
});

export default QRCode;
